package com.inventra.backend.controller; import com.inventra.backend.dto.RecommendationResponse; import com.inventra.backend.service.RecommendationService; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/recommendations") public class RecommendationController {private final RecommendationService s;public RecommendationController(RecommendationService s){this.s=s;}@GetMapping("/products/{productId}") public List<RecommendationResponse> recommend(@PathVariable String productId){return s.recommend(productId);}}
